import{_ as t,C as r,o as l,c as n,j as i,E as s,a as e,a3 as d}from"./chunks/framework.C6R8kWFE.js";const q=JSON.parse('{"title":"3-hafta","description":"","frontmatter":{"title":"3-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"10-sinf (Android)","link":"/10-sinf-android/"},"n":3,"bob":"I-bob · Android loyihalarini boshqarish va versiya nazorati tizimlari","lessons":[{"g":7,"title":"7-dars: Git bilan versiya nazorati asoslari","lead":"Git bilan versiya nazorati asoslari: Git repository, commit, log, .gitignore","link":"/10-sinf-android/hafta-03/dars-1","slide":"/slaydlar/10-sinf-android/hafta-03/dars-1.html","test":"/slaydlar/10-sinf-android/hafta-03/dars-1-test.html"},{"g":8,"title":"8-dars: Git bilan ishlash amaliyoti (Tarmoqlar va Konfliktlar)","lead":">>>>>> feature-api","link":"/10-sinf-android/hafta-03/dars-2","slide":"/slaydlar/10-sinf-android/hafta-03/dars-2.html","test":"/slaydlar/10-sinf-android/hafta-03/dars-2-test.html"},{"g":9,"title":"9-dars: GitHub’da loyihalar yaratish va boshqarish","lead":"GitHub’da loyihalar yaratish va boshqarish: remote repozitoriy, push, pull, issues, README","link":"/10-sinf-android/hafta-03/dars-3","slide":"/slaydlar/10-sinf-android/hafta-03/dars-3.html","test":"/slaydlar/10-sinf-android/hafta-03/dars-3-test.html"}],"test":"/slaydlar/10-sinf-android/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"10-sinf-android/hafta-03/index.md","filePath":"10-sinf-android/hafta-03/index.md"}'),h={name:"10-sinf-android/hafta-03/index.md"},c={class:"blk"},g={id:"uyga-vazifa",tabindex:"-1"};function f(y,a,m,u,b,v){const o=r("Icon");return l(),n("div",null,[i("div",c,[i("h2",g,[s(o,{name:"house"}),a[0]||(a[0]=e(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar to&#39;plami. Har bir vazifa 25–30 daqiqaga mo&#39;ljallangan.</p><hr><h3 id="_7-dars-git-bilan-versiya-nazorati-asoslari" tabindex="-1">7-dars: Git bilan versiya nazorati asoslari <a class="header-anchor" href="#_7-dars-git-bilan-versiya-nazorati-asoslari" aria-label="Permalink to &quot;7-dars: Git bilan versiya nazorati asoslari&quot;">​</a></h3><ol><li>Kompyuteringiz terminalida <code>git config --list</code> buyrug&#39;ini ishga tushiring va ismingiz hamda pochtangiz to&#39;g&#39;ri sozlanganini tasdiqlang.</li><li>Yangi papka ochib, <code>git init</code> orqali ombor yarating.</li><li>Loyihada <code>.gitignore</code> faylini ochib, Android uchun eng zarur qoidalarni kiriting: <ul><li><code>.gradle/</code>, <code>build/</code>, <code>app/build/</code></li><li><code>local.properties</code></li><li><code>*.apk</code>, <code>*.aab</code></li></ul></li><li>Kamida 3 ta turli fayl yaratib, ketma-ket 3 ta ma&#39;noli commitni (<code>feat: ...</code>, <code>fix: ...</code>, <code>docs: ...</code>) amalga oshiring va <code>git log --oneline</code> buyrug&#39;i natijasini ko&#39;ring.</li></ol><hr><h3 id="_8-dars-git-bilan-ishlash-amaliyoti-tarmoqlar-va-konfliktlar" tabindex="-1">8-dars: Git bilan ishlash amaliyoti (Tarmoqlar va Konfliktlar) <a class="header-anchor" href="#_8-dars-git-bilan-ishlash-amaliyoti-tarmoqlar-va-konfliktlar" aria-label="Permalink to &quot;8-dars: Git bilan ishlash amaliyoti (Tarmoqlar va Konfliktlar)&quot;">​</a></h3><ol><li>Loyihangizda <code>feature-settings</code> nomli yangi branch oching (<code>git switch -c feature-settings</code>).</li><li>Yangi branchda <code>AppSettings.kt</code> faylini yarating va unga boshlang&#39;ich sozlamalarni yozib commit qiling.</li><li>Asosiy <code>main</code> tarmog&#39;iga qaytib (<code>git switch main</code>), o&#39;zgarishlarni <code>git merge feature-settings</code> buyrug&#39;i bilan birlashtiring. So&#39;ngra eski branchni <code>git branch -d feature-settings</code> orqali o&#39;chiring.</li><li>Bitta fayl ichida sun&#39;iy to&#39;qnashuv (Merge Conflict) hosil qiling, uni qo&#39;lda to&#39;g&#39;rilab, to&#39;qnashuv belgilarini o&#39;chirib, muvaffaqiyatli merge commitini amalga oshiring.</li></ol><hr><h3 id="_9-dars-github-da-loyihalar-yaratish-va-boshqarish" tabindex="-1">9-dars: GitHub’da loyihalar yaratish va boshqarish <a class="header-anchor" href="#_9-dars-github-da-loyihalar-yaratish-va-boshqarish" aria-label="Permalink to &quot;9-dars: GitHub’da loyihalar yaratish va boshqarish&quot;">​</a></h3><ol><li>O&#39;zingizning shaxsiy GitHub akkauntingizda yangi Public repozitoriy yarating.</li><li>Lokal kompyuteringizdagi Android loyihasini masofaviy GitHub repozitoriyasiga ulang (<code>git remote add origin ...</code>) va barcha commitlarni <code>git push -u origin main</code> orqali yuklang.</li><li>Loyihangiz uchun Markdown formatida chiroyli va tushunarli <code>README.md</code> faylini yozing: <ul><li>Loyiha nomi va vazifasi;</li><li>Ishlatilgan kutubxonalar va texnologiyalar;</li><li>Qanday o&#39;rnatish va ishga tushirish bo&#39;yicha qo&#39;llanma.</li></ul></li><li>Repozitoriyda 2 ta yangi &quot;Issue&quot; oching: biri rejadagi funksiya haqida, ikkinchisi xatolik haqida. Ulardan birini commit xabarida <code>fixes #...</code> deb yozish orqali avtomatik yoping.</li></ol><hr>',11))])])}const p=t(h,[["render",f]]);export{q as __pageData,p as default};
